struct MusicEngine:PlaybackPort{
 int opens=0,stops=0,overlap=0;int64_t at=0;bool active=false,paused_state=false,failed=false,ended=false,retain_stop=false;
 bool open(const std::string&,int64_t p)override{if(active)++overlap;++opens;active=true;paused_state=failed=ended=false;at=p;return true;}
 void stop()override{++stops;if(retain_stop)return;active=false;at=0;}int64_t position()const override{return at;}bool paused()const override{return paused_state;}void pause()override{paused_state=!paused_state;}void seek(int64_t p)override{at=p;}
 PlaybackObservation observe()const override{return {true,active&&!paused_state&&!ended&&!failed,false,active&&paused_state,ended,failed};}
};
